def extractall(source: Path, dest: Path, zip: bool) -> None:
    if zip:
        with zipfile.ZipFile(source) as archive:
            archive.extractall(dest)
    else:
        broken_tarfile_filter = {(3, 10, 12), (3, 11, 4)}
        with tarfile.open(source) as archive:
            if hasattr(tarfile, "data_filter") and sys.version_info[:3] not in broken_tarfile_filter:
                archive.extractall(dest, filter="data")
            else:
                dest = Path(os.path.abspath(dest))
                safe_members = []
                for member in archive.getmembers():
                    member_path = Path(os.path.abspath(dest / member.name))
                    if not member_path.is_relative_to(dest):
                        raise ValueError(f"Refusing to extract {member.name}: would write outside {dest}")
                    if member.issym():
                        link_target = Path(os.path.abspath(member_path.parent / member.linkname))
                        if not link_target.is_relative_to(dest):
                            raise ValueError(f"Refusing symlink {member.name}: target outside {dest}")
                    elif member.islnk():
                        link_target = Path(os.path.abspath(dest / member.linkname))
                        if not link_target.is_relative_to(dest):
                            raise ValueError(f"Refusing hardlink {member.name}: target outside {dest}")
                    safe_members.append(member)
                archive.extractall(dest, members=safe_members)
